const [steps, setSteps] = useState([]);
const [busy, setBusy] = useState(false);

// from your stream: one object per reasoning / tool / approval part, stable ids, newest last
// { id: 'p1', kind: 'tool', title: 'Look up order 1042', tool: 'orders.lookup', state: 'input-available', input, startedAt: Date.now() }

<AgentSteps
  task="Refund order 1042"
  agent={{ name: 'Ops agent', by: user.name }}
  steps={steps}
  busy={busy}
  onApprove={async (id, { always }) => { setBusy(true); await agent.approve(id, { always }); setBusy(false); }}
  onReject={(id) => agent.reject(id)}
  onRetry={(id) => agent.retry(id)}
  onStop={() => agent.stop()}
/>
